import{_ as s,o as a,c as n,X as l}from"./chunks/framework.6bc268d3.js";const e="/blog/assets/makefile-img.3bb42663.png",p="/blog/assets/makefile-WorkingPrinciple1.d055d328.png",o="/blog/assets/makefile-WorkingPrinciple2.567d2ca7.png",c="/blog/assets/example.ce7bdb06.png",r="/blog/assets/running_result0.b8c40c23.png",t="/blog/assets/running_result1.3a5a69c0.png",i="/blog/assets/running_result2.7c9fbd8f.png",k=JSON.parse('{"title":"MakeFile配置详解","description":"","frontmatter":{},"headers":[],"relativePath":"markdown/golang/other/makefile.md","filePath":"markdown/golang/other/makefile.md","lastUpdated":1718183641000}'),A={name:"markdown/golang/other/makefile.md"},D=l('<h1 id="makefile配置详解" tabindex="-1">MakeFile配置详解 <a class="header-anchor" href="#makefile配置详解" aria-label="Permalink to &quot;MakeFile配置详解&quot;">​</a></h1><p>资料来源：<br><a href="https://developer.aliyun.com/article/1488371" target="_blank" rel="noreferrer">Makefile(1)入门</a><br><a href="https://developer.aliyun.com/article/1488378" target="_blank" rel="noreferrer">Makefile(2)原理</a></p><p>Makefile 是一个用于构建和编译程序的工具，它使用规则来描述如何编译和链接源代码文件。<br> Makefile 的核心思想是，通过定义一系列规则来描述如何生成目标文件，然后通过执行这些规则来生成目标文件。</p><p>想要掌握makefle，首先需要了解两个概念，一个是目标(target)，另一个就是依赖(dependency)。目标就是指要干什么，或说运行 make 后生成什么，而依赖是告诉 make 如何去做以实现目标。在 Makefile 中，目标和依赖是通过规则(rule)来表达的。</p><p><img src="'+e+'" alt="makefile示意图"></p><p><img src="'+p+'" alt="makefile工作原理1"></p><p><img src="'+o+`" alt="makefile工作原理2"></p><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><div class="language-MakeFile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">MakeFile</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">all</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#A6ACCD;">    echo &quot;hello world&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>上面Makefile 中的 <code>all</code> 就是我们 的目标，目标放在 <code>:</code> 的前面，其名字可以是由字母和下划线<code>_</code>组成。 echo &quot;Helo Worid&quot;就是生成目标的命令，这些命令可以是任何你可以在你的环境中运行的命令以及 make 所定义的函数等等。 <code>all</code> 目标的定义，其实是定义了如何生成 <code>all</code> 目标，这我们也称之为规则。</p></blockquote><div class="language-MakeFile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">MakeFile</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">all</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#A6ACCD;">    echo &quot;hello world&quot;</span></span>
<span class="line"><span style="color:#82AAFF;">test</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#A6ACCD;">    @echo &quot;test game&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>顺序运行结果如下：<code>make all</code> <code>make test</code></p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">hello world</span></span>
<span class="line"><span style="color:#A6ACCD;">test game</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="danger custom-block"><p class="custom-block-title">提示</p><p>一个 <strong>Makefile</strong> 中可以定义多个目标。调用 make 命令时，我们得告诉它我们的目标是什么，即要它干什么。当没有指明具体的目标是什么 时，那么 make 以 Makefile 文件中定义的第一个目标作为这次运行的目标。这&quot;第一个&quot;目标也称之为默认目标(和是不是all没有关系)。当 make 得到目标后，先找到定义目标的规则，然后运行规则中的命令来达到构建目标的目的。</p></div><p>紧接着对makefle进行如下的改动，在all的后面加上test</p><div class="language-MakeFile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">MakeFile</span><pre class="shiki material-theme-palenight has-diff"><code><span class="line diff remove"><span style="color:#82AAFF;">all</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span></span>
<span class="line diff add"><span style="color:#82AAFF;">all</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> test </span></span>
<span class="line"><span style="color:#A6ACCD;">    echo &quot;hello world&quot;</span></span>
<span class="line"><span style="color:#82AAFF;">test</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#A6ACCD;">    @echo &quot;test game&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>如上， all 是目标，test是 all 目标的依赖目标，而@echo “Hello World&quot;则是用于生成 all 目标的命令。</p><p>运行结果如下：<code>make all</code></p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">test game</span></span>
<span class="line"><span style="color:#A6ACCD;">hello world</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>如上图所示text也被构建了</p><h2 id="依赖" tabindex="-1">依赖 <a class="header-anchor" href="#依赖" aria-label="Permalink to &quot;依赖&quot;">​</a></h2><p>如上面的makefile，all目标后面的 test 是告诉 make，all目标依赖 test 目标，这一依赖目标在Makefile 中又被称之为先决条件。出现这种目标依赖关系时，make工具会按 从左到右的先后顺序先构建规则中所依赖的每一个目标。如果希望构建 all 目标，那么make 会在构建它之 前得先构建 test目标，这就是为什么我们称之为先决条件的原因。</p><h2 id="规则" tabindex="-1">规则 <a class="header-anchor" href="#规则" aria-label="Permalink to &quot;规则&quot;">​</a></h2><p><strong>一个规则是由目标(targets)、先决条件(prerequisites)以及命令(commands)所组成的。</strong></p><p>需要指出的是，目标和先决条件之间表达的就是依赖关系(dependency)，这种依赖关系指明在构建目标之前，必须保证先决条件先满足(或构建)。而先决条件可以是其它的目标，当先决条件是目标时，其必须先被构建出来。</p><div class="danger custom-block"><p class="custom-block-title">提示</p><p>一个规则中目标可以有多个，当存在多个目标，且这一规则是 Makefile 中的第一个规则时，如果我们运行 make 命令不带任何目标，那么规则中的第一个目标将被视为是缺省目标。</p></div><p><strong>规则的功能就是指明 make 什么时候以及如何来为我们重新创建目标</strong>，在 Hello Word 例子中，不论我们 在什么时候运行 make 命令(带目标或是不带目标)，其都会在终端上打印出信息来，和我们采用 make 进行代码编译时的表现好象有些不同。当采用 Makefle 来编译程序时，如果两次编译之间没有任何代码 的改动，理论上说来，我们是不希望看到 make 会有什么动作的，只需说“目标是最新的”，而我们的最终 目标也是希望构建出一个“聪明的&quot;Makefile 的。与 Hello Worid 相比不同的是，采用 Makefile 来进行 代码编译时，Makefile 中所存在的先决条件都是具体的程序文件，后面我们会看到。</p><h3 id="规则语法" tabindex="-1">规则语法 <a class="header-anchor" href="#规则语法" aria-label="Permalink to &quot;规则语法&quot;">​</a></h3><div class="language-MakeFile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">MakeFile</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">targets(目标)</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> prerequisites(依赖)</span></span>
<span class="line"><span style="color:#A6ACCD;">    command(命令)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="makefile的原理" tabindex="-1">makefile的原理 <a class="header-anchor" href="#makefile的原理" aria-label="Permalink to &quot;makefile的原理&quot;">​</a></h3><div class="language-C line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#676E95;font-style:italic;">// foo.c</span></span>
<span class="line"><span style="color:#A6ACCD;">voif </span><span style="color:#82AAFF;">foo</span><span style="color:#89DDFF;">()</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#F07178;">  </span><span style="color:#82AAFF;">printf</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">this is foo() !</span><span style="color:#A6ACCD;">\\n</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">);</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><div class="language-C line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki material-theme-palenight has-highlighted-lines"><code><span class="line"><span style="color:#676E95;font-style:italic;">// main.c</span></span>
<span class="line"><span style="color:#C792EA;">extern</span><span style="color:#A6ACCD;"> </span><span style="color:#C792EA;">void</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">foo</span><span style="color:#89DDFF;">();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C792EA;">int</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">main</span><span style="color:#89DDFF;">()</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line highlighted"><span style="color:#F07178;">  </span><span style="color:#82AAFF;">foo</span><span style="color:#89DDFF;">();</span></span>
<span class="line"><span style="color:#F07178;">  </span><span style="color:#89DDFF;font-style:italic;">return</span><span style="color:#F07178;"> </span><span style="color:#F78C6C;">0</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="language-makefile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">all</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> main.o foo.o </span></span>
<span class="line"><span style="color:#A6ACCD;">  gcc -o simple main.o foo.o </span></span>
<span class="line"><span style="color:#82AAFF;">main.o</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> main.c</span></span>
<span class="line"><span style="color:#A6ACCD;">  gcc -o main.o -c main.c</span></span>
<span class="line"><span style="color:#82AAFF;">foo.o</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> foo.c</span></span>
<span class="line"><span style="color:#A6ACCD;">  gcc -o foo.o -c foo.c</span></span>
<span class="line"><span style="color:#82AAFF;">clean</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> rm simple main.o foo.o</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><blockquote><p>1.目标 all 是默认目标，表示在命令行中只运行 make 时，将执行该目标。<br> 2.它依赖于 main.o 和 foo.o 两个目标。<br> 3.当 main.o 和 foo.o 都已存在，将 main.o 和 foo.o 链接成一个名为 simple 的可执行文件。</p></blockquote><p>上面三段代码生成的依赖树 <img src="`+c+'" alt="示例"></p><p>运行结果： <img src="'+r+`" alt="运行结果0"></p><p>第二次编译虽未构建目标文件的动作,但却有构建<code>simple</code>可执行程序的动作? 我们需要了解 <code>make</code> 是如何决定哪些目标(这里是文件)是需要重新编译的。通过文件的时间戳<code>make</code>会知道我们是否改变<code>main.c</code>和<code>foo.c</code>文件内容。</p><p>当 <code>make</code> 在运行一个规则时，我们前面已经提到了目标和先决条件之间的依赖关系 <code>make</code> 在检查一个规则时,采用的方法是：<br><strong>如果先决条件中相关的文件的时间戳大于目标的时间戳，即先决条件中的文件比目标更新，则知道有变化那么需要运行规则当中的命令重新构建目标。</strong></p><p>这条规则会运用到所有与我们在make时指定的目标的依赖树中的每一个规则。比如，对于<code>simple</code>项目，其依赖树中包括三个规则，make 会检查所有三个规则当中的<code>目标(文件)</code>与<code>先决条件(文件)</code>之间的时间先后关系，从而来决定是否要重新创建规则中的目标。</p><h3 id="问题一-第二次构建的时候为什么simple会被重新构建" tabindex="-1">问题一：第二次构建的时候为什么simple会被重新构建? <a class="header-anchor" href="#问题一-第二次构建的时候为什么simple会被重新构建" aria-label="Permalink to &quot;问题一：第二次构建的时候为什么simple会被重新构建?&quot;">​</a></h3><p>是因为simple文件不存在，我们在这次构建的目标是all，而all在我们编译的过成中并不生成，所以第二次make的时候找不到，所以又重新编译了一遍。</p><div class="language-makefile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki material-theme-palenight has-diff"><code><span class="line diff remove"><span style="color:#82AAFF;">all</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> main.o foo.o </span></span>
<span class="line diff add"><span style="color:#82AAFF;">simple</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> main.o foo.o </span></span>
<span class="line"><span style="color:#A6ACCD;">  gcc -o simple main.o foo.o </span></span>
<span class="line"><span style="color:#82AAFF;">main.o</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> main.c</span></span>
<span class="line"><span style="color:#A6ACCD;">  gcc -o main.o -c main.c</span></span>
<span class="line"><span style="color:#82AAFF;">foo.o</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> foo.c</span></span>
<span class="line"><span style="color:#A6ACCD;">  gcc -o foo.o -c foo.c</span></span>
<span class="line"><span style="color:#82AAFF;">clean</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> rm simple main.o foo.o</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>运行结果： <img src="`+t+'" alt="运行结果1"></p><p>文件的改变不是看文件大小变化，而是文件时间戳的变化。</p><blockquote><p><code>ls -l</code>命令查看文件时间戳<br><code>touch xxx</code>命令修改文件时间戳</p></blockquote><p><img src="'+i+`" alt="运行结果2"></p><h3 id="假目标" tabindex="-1">假目标 <a class="header-anchor" href="#假目标" aria-label="Permalink to &quot;假目标&quot;">​</a></h3><p>如果我们的创建了一个clean文件之后，继续去运行make clean，这时候不是按照我们前面运行的make clean进行清理文件。</p><p>因为make将clean当成是一个文件，并且在当前的目录下找到了这个文件，再加上clean目标没有任何的先决条件，这时候进行make clean时，系统会认为clean是最新的。</p><p>使用假目标，假目标最从常用清净就是避免所定义的目标和的已经存在文件是从重名的情况，假⽬标可以采⽤<code>.PHONY</code> 关键字来定义，需要注意的是其必须是⼤写字⺟。使用假目标修改makefile。</p><div class="language-makefile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki material-theme-palenight has-diff"><code><span class="line diff add"><span style="color:#82AAFF;">.PHONY</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> clean  </span></span>
<span class="line"><span style="color:#82AAFF;">simple</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> main.o foo.o</span></span>
<span class="line"><span style="color:#A6ACCD;">  gcc -o simple main.o foo.o</span></span>
<span class="line"><span style="color:#82AAFF;">main.o</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> main.c</span></span>
<span class="line"><span style="color:#A6ACCD;">  gcc -o main.o -c main.c</span></span>
<span class="line"><span style="color:#82AAFF;">foo.o</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> foo.c</span></span>
<span class="line"><span style="color:#A6ACCD;">  gcc -o foo.o -c foo.c</span></span>
<span class="line"><span style="color:#82AAFF;">clean</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> rm simple main.o foo.o</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>采⽤<code>.PHONY</code> 关键字声明⼀个⽬标后，make 并不会将其当作⼀个⽂件来处理，⽽只是当作⼀个概念上的⽬标。对于假⽬标，我们可以想像的是由于并不与⽂件关联，所以每⼀次 make 这个假⽬标时，其所在的规则中的命令都会被执⾏。</p><blockquote><p><code>-j</code> 或 <code>--jobs</code> 选项用于指定同时运行的任务数。 <code>-j24</code> 表示同时运行最多 24 个任务。 例子：make -j24</p></blockquote><h2 id="变量" tabindex="-1">变量 <a class="header-anchor" href="#变量" aria-label="Permalink to &quot;变量&quot;">​</a></h2><p>先看代码</p><div class="language-makefile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">.PHONY</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> clean</span></span>
<span class="line"><span style="color:#A6ACCD;">CC </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> gcc</span></span>
<span class="line"><span style="color:#A6ACCD;">RM </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> rm</span></span>
<span class="line"><span style="color:#A6ACCD;">EXE </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> simple</span></span>
<span class="line"><span style="color:#A6ACCD;">OBJS </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> main.o foo.o</span></span>
<span class="line"><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">EXE</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;">: </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">OBJS</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">CC</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> -o </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">EXE</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">OBJS</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#82AAFF;">main.o</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> main.c</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">CC</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> -o main.o -c main.c</span></span>
<span class="line"><span style="color:#82AAFF;">foo.o</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> foo.c</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">CC</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> -o foo.o -c foo.c</span></span>
<span class="line"><span style="color:#82AAFF;">clean</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">RM</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">EXE</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">OBJS</span><span style="color:#89DDFF;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>变量的使用可以提高makefile的可维护性。⼀个变量的定义很简单，就是⼀个名字（变量名）后⾯跟上⼀个等号，然后在等号的后⾯放这个变量所期望的值。对于变量的引⽤，则需要采⽤<code>$(变量名)</code>或者<code>\${变量名}</code>这种模式。</p><p>在这个 Makefile 中，我们引⼊了 <code>CC</code> 和 <code>RM</code> 两个变量，⼀个⽤于保存编译器名，⽽另⼀个⽤于指示删除⽂件的命令是什么。还有就是引⼊了 <code>EXE</code> 和 <code>OBJS</code> 两个变量，⼀个⽤于存放可执⾏⽂件名，可另⼀个则⽤于放置所有的⽬标⽂件名。采⽤变量的话，当我们需要更改编译器时，只需更改变量赋值的地⽅，⾮常⽅便，如果不采⽤变量，那我们得更改每⼀个使⽤编译器的地⽅，很是麻烦。</p><h2 id="自动变量-☆☆☆☆☆" tabindex="-1">自动变量（☆☆☆☆☆） <a class="header-anchor" href="#自动变量-☆☆☆☆☆" aria-label="Permalink to &quot;自动变量（☆☆☆☆☆）&quot;">​</a></h2><p>对于每⼀个规则，⽬标和先决条件的名字会在规则的命令中多次出现，每⼀次出现都是⼀种麻烦，更为麻烦的是，如果改变了⽬标或是依赖的名，那得在命令中全部跟着改。有没有简化这种更改的⽅法呢？这我们需要⽤到 Makefile 中的⾃动变量，最常用包括：</p><ul><li><strong>$@⽤于表示⼀个规则中的⽬标。当我们的⼀个规则中有多个⽬标时，$@所指的是其中任何造成命令被运⾏的⽬标。</strong></li><li><strong>$^则表示的是规则中的所有先择条件。</strong></li><li><strong>$&lt;表示的是规则中的第⼀个先决条件。</strong></li></ul><div class="language-makefile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">.PHONY</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;">all</span></span>
<span class="line"><span style="color:#82AAFF;">all</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;">first second third</span></span>
<span class="line"><span style="color:#A6ACCD;">    @echo &quot;\\$$@ = $@&quot;</span></span>
<span class="line"><span style="color:#A6ACCD;">    @echo &quot;\\$$^ = $^&quot;</span></span>
<span class="line"><span style="color:#A6ACCD;">    @echo &quot;\\$$&lt; = $&lt;&quot;</span></span>
<span class="line"><span style="color:#A6ACCD;"> </span></span>
<span class="line"><span style="color:#82AAFF;">first</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">second</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">third</span><span style="color:#89DDFF;">:</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>运行结果</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">xxxxxx# make</span></span>
<span class="line"><span style="color:#A6ACCD;">$@ = all</span></span>
<span class="line"><span style="color:#A6ACCD;">$^ = first second third</span></span>
<span class="line"><span style="color:#A6ACCD;">$&lt; = first</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>需要注意的是，在 Makefile 中<code>$</code>具有特殊的意思，因此，如果想采⽤ echo 输出<code>$</code>，则必需⽤两个连着的<code>$</code>。还有就是，<code>$@</code>对于 Shell 也有特殊的意思，我们需要在<code>$$@</code>之前再加⼀个脱字符<code>\\</code>。</p><p>修改simple的makefile</p><div class="language-makefile line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">.PHONY</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> clean</span></span>
<span class="line"><span style="color:#A6ACCD;">CC </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> gcc</span></span>
<span class="line"><span style="color:#A6ACCD;">RM </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> rm</span></span>
<span class="line"><span style="color:#A6ACCD;">EXE </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> simple</span></span>
<span class="line"><span style="color:#A6ACCD;">OBJS </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> main.o foo.o</span></span>
<span class="line"><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">EXE</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;">: </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">OBJS</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">CC</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> -o $@ $^</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#82AAFF;">@echo</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">&quot;&gt;&gt;&gt;&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">simple</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">CC</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> -o $@ $^&quot;</span></span>
<span class="line"><span style="color:#82AAFF;">main.o</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> main.c</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">CC</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> -o $@ -c $^</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#82AAFF;">@echo</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">&quot;&gt;&gt;&gt;&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">main</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">CC</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> -o $@ -c $^&quot;</span></span>
<span class="line"><span style="color:#82AAFF;">foo.o</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> foo.c</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">CC</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> -o $@ -c $^</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#82AAFF;">@echo</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">&quot;&gt;&gt;&gt;&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">foo</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">CC</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> -o $@ -c $^&quot;</span></span>
<span class="line"><span style="color:#82AAFF;">clean</span><span style="color:#89DDFF;">:</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">RM</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">EXE</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">OBJS</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#82AAFF;">@echo</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">&quot;&gt;&gt;&gt;&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">clean</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">RM</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">EXE</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$(</span><span style="color:#A6ACCD;">OBJS</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;">&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><h3 id="_1-符号" tabindex="-1">1.符号 <a class="header-anchor" href="#_1-符号" aria-label="Permalink to &quot;1.符号&quot;">​</a></h3><h4 id="_1-命令前缀" tabindex="-1">1) 命令前缀 <a class="header-anchor" href="#_1-命令前缀" aria-label="Permalink to &quot;1) 命令前缀&quot;">​</a></h4><p>[不用前缀] 输出执行的<strong>命令</strong>以及<strong>命令执行结果</strong>, 出错的话停止执行<br> [前缀<code>@</code>] 只输出<strong>命令执行结果</strong>, 出错的话停止执行<br> [前缀<code>-</code>] 命令执行有错的话, 忽略错误, 继续执行</p>`,71),m=[D];function C(y,d,F,b,u,h){return a(),n("div",null,m)}const f=s(A,[["render",C]]);export{k as __pageData,f as default};
